32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
42	import org.springframework.samples.petclinic.rest.advice.DailyRegistrationLimitException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
47	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
48	import org.springframework.samples.petclinic.rest.api.OwnersApi;
49	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
50	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.PetDto;
52	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
53	import org.springframework.samples.petclinic.rest.dto.VisitDto;
54	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
75	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
76	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
80	
81	    /** Dedicated audit logger; carries owner lifecycle side-effects. */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
99	        this.visitMapper = visitMapper;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        if (isBlank(ownerFieldsDto.getFirstName())) {
132	            missingFields.add("firstName");
133	        }
134	        if (isBlank(ownerFieldsDto.getLastName())) {
135	            missingFields.add("lastName");
136	        }
137	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
138	        if (isBlank(normalizedAddress)) {
139	            missingFields.add("address");
140	        }
141	        if (isBlank(ownerFieldsDto.getCity())) {
142	            missingFields.add("city");
143	        }
144	        if (isBlank(ownerFieldsDto.getTelephone())) {
145	            missingFields.add("telephone");
146	        }
147	        if (!missingFields.isEmpty()) {
148	            throw new MissingOwnerFieldsException(missingFields);
149	        }
150	        LocalDate registrationDate = toBusinessDay(
151	            ownerFieldsDto.getRegistrationDate() != null
152	                ? ownerFieldsDto.getRegistrationDate()
153	                : LocalDate.now());
154	        long registeredOnDay = this.clinicService.findAllOwners().stream()
155	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
156	            .count();
157	        if (registeredOnDay >= 100) {
158	            throw new DailyRegistrationLimitException(
159	                "100 or more owners have already been registered today");
160	        }
161	        String city = ownerFieldsDto.getCity();
162	        long ownersInCity = this.clinicService.findAllOwners().stream()
163	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
164	            .count();
165	        if (ownersInCity >= 50) {
166	            throw new CityAtCapacityException(
167	                "the owner's city already contains 50 or more owners");
168	        }
169	        ownerFieldsDto.setAddress(normalizedAddress);
170	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
171	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
172	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
173	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
174	            .toList();
175	        String householdId = null;
176	        if (!householdMembers.isEmpty()) {
177	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
178	                throw new DuplicateHouseholdException(
179	                    "an owner with the same last name and address already exists");
180	            }
181	            // Joining an existing household: share a stable identifier with every member,
182	            // backfilling any members created before the household was formed.
183	            householdId = householdId(lastName, normalizedAddress);
184	            for (Owner member : householdMembers) {
185	                if (!householdId.equals(member.getHouseholdId())) {
186	                    member.setHouseholdId(householdId);
187	                    this.clinicService.saveOwner(member);
188	                }
189	            }
190	        }
191	        String telephone = toE164(ownerFieldsDto.getTelephone());
192	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
193	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
194	        if (telephoneInUse) {
195	            throw new DuplicateTelephoneException(
196	                "an owner with the same E.164 telephone already exists");
197	        }
198	        ownerFieldsDto.setTelephone(telephone);
199	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
200	        HttpHeaders headers = new HttpHeaders();
201	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
202	        owner.setRegistrationDate(registrationDate);
203	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
204	        owner.setHouseholdId(householdId);
205	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
206	        this.clinicService.saveOwner(owner);
207	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
208	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
210	        headers.setLocation(UriComponentsBuilder.newInstance()
211	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
212	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
218	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
219	        if (currentOwner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        currentOwner.setAddress(ownerFieldsDto.getAddress());
223	        currentOwner.setCity(ownerFieldsDto.getCity());
224	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
225	        currentOwner.setLastName(ownerFieldsDto.getLastName());
226	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
227	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
228	        this.clinicService.saveOwner(currentOwner);
229	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Transactional
234	    @Override
235	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
236	        Owner owner = this.clinicService.findOwnerById(ownerId);
237	        if (owner == null) {
238	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	        }
240	        this.clinicService.deleteOwner(owner);
241	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
247	        Owner owner = this.clinicService.findOwnerById(ownerId);
248	        if (owner == null) {
249	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
250	        }
251	        HttpHeaders headers = new HttpHeaders();
252	        Pet pet = petMapper.toPet(petFieldsDto);
253	        owner.setId(ownerId);
254	        pet.setOwner(owner);
255	        pet.getType().setName(null);
256	        this.clinicService.savePet(pet);
257	        PetDto petDto = petMapper.toPetDto(pet);
258	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
259	            .buildAndExpand(pet.getId()).toUri());
260	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
261	    }
262	
263	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
264	    @Override
265	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
266	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
267	        if (currentOwner != null) {
268	            Pet currentPet = this.clinicService.findPetById(petId);
269	            if (currentPet != null) {
270	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
271	                currentPet.setName(petFieldsDto.getName());
272	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
273	                this.clinicService.savePet(currentPet);
274	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
275	            }
276	        }
277	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
278	    }
279	
280	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
281	    @Override
282	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
283	        HttpHeaders headers = new HttpHeaders();
284	        Visit visit = visitMapper.toVisit(visitFieldsDto);
285	        Pet pet = new Pet();
286	        pet.setId(petId);
287	        visit.setPet(pet);
288	        this.clinicService.saveVisit(visit);
289	        VisitDto visitDto = visitMapper.toVisitDto(visit);
290	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
291	            .buildAndExpand(visit.getId()).toUri());
292	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
293	    }
294	
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
299	        Owner owner = this.clinicService.findOwnerById(ownerId);
300	        if (owner != null) {
301	            Pet pet = owner.getPet(petId);
302	            if (pet != null) {
303	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
304	            }
305	        }
306	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
307	    }
308	
309	    private static boolean isBlank(String value) {
310	        return value == null || value.isBlank();
311	    }
312	
313	    /**
314	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
315	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
316	     * to the effective registration date (whether supplied in the request or defaulted to the server
317	     * date), so every value derived from the registration date sees the adjusted business day.
318	     */
319	    private static LocalDate toBusinessDay(LocalDate date) {
320	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
321	            date = date.plusDays(1);
322	        }
323	        return date;
324	    }
325	
326	    /**
327	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
328	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
329	     * lower-cased so that last names are compared case-insensitively.
330	     */
331	    private static String normalizeHousehold(String value) {
332	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
333	    }
334	
335	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
336	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
337	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
338	
339	    /**
340	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
341	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
342	     * upper-cased, and common street-type abbreviations are expanded token-by-token
343	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
344	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
345	     * used for every address comparison (household-duplicate detection and the shared household id).
346	     */
347	    private static String normalizeAddress(String value) {
348	        if (value == null) {
349	            return "";
350	        }
351	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
352	        if (collapsed.isEmpty()) {
353	            return "";
354	        }
355	        String[] tokens = collapsed.split(" ");
356	        StringBuilder sb = new StringBuilder();
357	        for (int i = 0; i < tokens.length; i++) {
358	            if (i > 0) {
359	                sb.append(' ');
360	            }
361	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
362	        }
363	        return sb.toString();
364	    }
365	
366	    /**
367	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
368	     * deterministic function of the normalized last name and address, so every owner that
369	     * shares those values maps to the same identifier regardless of creation order.
370	     */
371	    private static String householdId(String normalizedLastName, String normalizedAddress) {
372	        String key = normalizedLastName + "\n" + normalizedAddress;
373	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
374	    }
375	
376	    /**
377	     * Builds the {@code customerCode} assigned to a new owner, formatted
378	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
379	     * owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last name,
380	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number
381	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
382	     */
383	    private String nextCustomerCode(String city, String lastName) {
384	        String city3 = prefix3(city);
385	        String last3 = prefix3(lastName);
386	        long sequence = this.clinicService.findAllOwners().stream()
387	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
388	            .count() + 1L;
389	        return String.format("%s-%s-%04d", city3, last3, sequence);
390	    }
391	
392	    /** Upper-cased first three letters (any non-letter removed) of the given value. */
393	    private static String prefix3(String value) {
394	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
395	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
396	    }
397	
398	    /**
399	     * Counts the existing owners that share the given first name and last name, compared
400	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
401	     * owner currently being created is saved), so it reflects how many namesakes preceded the
402	     * new owner.
403	     */
404	    private int countNamesakes(String firstName, String lastName) {
405	        return (int) this.clinicService.findAllOwners().stream()
406	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
407	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
408	            .count();
409	    }
410	
411	    /**
412	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
413	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
414	     * national one, a single leading {@code '0'} is dropped, and the default country code
415	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
416	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
417	     */
418	    private static String toE164(String telephone) {
419	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
420	        String digits;
421	        if (cleaned.startsWith("+")) {
422	            digits = cleaned.substring(1);
423	        } else {
424	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
425	            digits = "61" + national;
426	        }
427	        if (!digits.matches("[0-9]{8,15}")) {
428	            throw new InvalidTelephoneException(
429	                "telephone must form a valid E.164 number with 8 to 15 digits");
430	        }
431	        return "+" + digits;
432	    }
433	
434	    /**
435	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
436	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
437	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
438	     * stored and returned in canonical form.
439	     */
440	    private static String normalizeEmail(String email) {
441	        if (isBlank(email)) {
442	            return null;
443	        }
444	        String trimmed = email.trim();
445	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
446	            throw new InvalidEmailException("email must be a syntactically valid address");
447	        }
448	        return trimmed.toLowerCase(Locale.ROOT);
449	    }
450	}
